// GitHub hottest files (#402) — heat-tinted grid of the hottest changed files. Extracted from
// GitHubPulse's inline card into its own composable record; adds the loading skeleton the inline
// version didn't have.
import { CardHead } from "@/shared/ui/charts";
import { SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { Grid } from "@/shared/ui/layout/Grid";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Card } from "@/shared/ui/data/Card";

export interface ChurnFile { p: string; w: number }

const DEMO_FILES: ChurnFile[] = [
  { p: "src/features/planner/Board.tsx", w: 640 }, { p: "src/shared/ui/data/Card.tsx", w: 420 },
  { p: "src/features/security/lib/agentProfiles.ts", w: 310 }, { p: "src/store/index.ts", w: 280 },
];

export function FileChurn({ files = DEMO_FILES, loading = false }: { files?: ChurnFile[]; loading?: boolean }) {
  if (loading) {
    return (
      <Card>
        <CardHead title="Hottest files" hint="±lines · recent commits · darker = hotter" />
        <SkeletonChart height={108} />
      </Card>
    );
  }
  if (!files.length) return null;
  const max = Math.max(...files.map((f) => f.w));
  return (
    <Card>
      <CardHead title="Hottest files" hint="±lines · recent commits · darker = hotter" />
      <Grid cols={4} gap={4}>
        {files.map((f) => {
          const t = f.w / max;
          const a = 0.16 + 0.74 * t;
          const dark = t > 0.55;
          return (
            <Stack key={f.p} title={`${f.p} · ±${f.w}`} className="mono" justify="between" style={{
              padding: "8px 9px", borderRadius: 4, minHeight: 52,
              background: `color-mix(in oklch, var(--accent) ${Math.round(a * 100)}%, var(--bg-elev))`,
              border: "1px solid var(--border-soft)",
              fontSize: 9.5, lineHeight: 1.35,
              overflow: "hidden",
            }}>
              <Box as="span" style={{ display: "block", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: dark ? "#1a120a" : "var(--fg)" }}>{f.p.split("/").pop()}</Box>
              <Box as="span" style={{ fontSize: 8.5, color: dark ? "#1a120a" : "var(--fg-dim)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{f.p.replace(/\/[^/]+$/, "") || "/"}</Box>
              <Text as="span" size={9.5} weight={600} style={{ color: dark ? "#1a120a" : "var(--fg-muted)" }}>±{f.w}</Text>
            </Stack>
          );
        })}
      </Grid>
    </Card>
  );
}
